///	Ring of Elemental Command (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class RingOfElementalCommand2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("ring-of-elemental-command", null, 0, MagicItemType.Ring, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(5, ItemRecharge.LongRest, "1d4+1"),
			("Anello del comando degli elementali", "Anello, leggendario (richiede sintonia)",
			"Questo anello è collegato a un Piano Elementale scelto dal GM o determinato in maniera casuale.\n\nFinché il personaggio indossa questo anello, dispone di vantaggio ai tiri per colpire contro gli elementali provenienti dal piano a esso collegato; questi ultimi, inoltre, subiscono svantaggio ai tiri per colpire contro di lui. Il personaggio ha anche accesso alle proprietà basate sul piano collegato.\n\nL'anello possiede 5 cariche e recupera 1d4 + 1 cariche consumate all'alba di ogni giorno. Gli incantesimi lanciati dall'anello hanno una CD del tiro salvezza pari a 17.\n\n***Anello del comando degli elementali del fuoco.*** Il personaggio può consumare 2 cariche dell'anello per lanciare *dominare mostri* su un elementale del fuoco. Inoltre, dispone di resistenza ai danni da fuoco. Può anche parlare e capire l'Ignan.\n\nSe il personaggio contribuisce a uccidere un elementale del fuoco mentre è in sintonia con l'anello, ottiene le seguenti proprietà aggiuntive:\n\n- Ottiene immunità ai danni da fuoco.\n\n- Può lanciare dall'anello gli incantesimi seguenti, consumando il numero necessario di cariche: *mani brucianti* (1 carica), *muro di fuoco* (3 cariche) o *palla di fuoco* (2 cariche).\n\n***Anello del comando degli elementali della terra.*** Il personaggio può consumare 2 cariche dell'anello per lanciare *dominare mostri* su un elementale della terra. Inoltre, può muoversi su un terreno difficile formato da macerie, rocce o terriccio come se fosse terreno normale. Può anche parlare e capire il Terran.\n\nSe il personaggio contribuisce a uccidere un elementale della terra mentre è in sintonia con l'anello, ottiene le seguenti proprietà aggiuntive:\n\n- Possiede resistenza ai danni da acido.\n\n- Può muoversi attraverso la terra solida o la roccia come se fossero aree di terreno difficile. Se termina il suo turno in una di queste aree, viene spostato nell'ultimo spazio libero che ha occupato.\n\n- Può lanciare dall'anello gli incantesimi seguenti, consumando il numero necessario di cariche: *muro di pietra* (3 cariche), *pelle di pietra* (3 cariche) o *scolpire pietra* (2 cariche).\n\n***Anello del comando degli elementali dell'acqua.*** Il personaggio può consumare 2 cariche dell'anello per lanciare *dominare mostri* su un elementale dell'acqua. Inoltre, può stare in piedi e camminare sulle superfici liquide come se fossero terreno solido. Può anche parlare e capire l'Aquan.\n\nSe il personaggio contribuisce a uccidere un elementale dell'acqua mentre è in sintonia con l'anello, ottiene le seguenti proprietà aggiuntive:\n\n- Può respirare sott'acqua e ha una velocità di nuotare pari alla sua velocità base sul terreno.\n\n- Può lanciare dall'anello gli incantesimi seguenti, consumando il numero necessario di cariche: *controllare acqua* (3 cariche), *creare o distruggere acqua* (1 carica), *muro di ghiaccio* (3 cariche) o *tempesta di ghiaccio* (2 cariche).\n\n***Anello del comando degli elementali dell'aria.*** Il personaggio può consumare 2 cariche dell'anello per lanciare *dominare mostri* su un elementale dell'aria. Inoltre, quando il personaggio cade, scende di 18 metri per round senza subire danni dalla caduta. Può anche parlare e capire l'Auran.\n\nSe il personaggio contribuisce a uccidere un elementale dell'aria mentre è in sintonia con l'anello, ottiene le seguenti proprietà aggiuntive:\n\n- Possiede resistenza ai danni da fulmine.\n\n- Possiede una velocità di volare pari alla sua velocità base e può fluttuare.\n\n- Può lanciare dall'anello gli incantesimi seguenti, consumando il numero necessario di cariche: *catena di fulmini* (3 cariche), *folata di vento* (2 cariche) o *muro di vento* (1 carica).", null),
			("Ring of Elemental Command", "Ring, legendary (requires attunement)",
			"This ring is linked to one of the four Elemental Planes. The GM chooses or randomly determines the linked plane.\n\nWhile wearing this ring, you have advantage on attack rolls against elementals from the linked plane, and they have disadvantage on attack rolls against you. In addition, you have access to properties based on the linked plane.\n\nThe ring has 5 charges. It regains 1d4 + 1 expended charges daily at dawn. Spells cast from the ring have a save DC of 17.\n\n***Ring of Air Elemental command.*** You can expend 2 of the ring's charges to cast dominate monster on an air elemental. In addition, when you fall, you descend 60 feet per round and take no damage from falling. You can also speak and understand Auran.\n\nIf you help slay an air elemental while attuned to the ring, you gain access to the following additional properties:\n\nYou have resistance to lightning damage.\n\nYou have a flying speed equal to your walking speed and can hover.\n\nYou can cast the following spells from the ring, expending the necessary number of charges: chain lightning (3 charges), gust of wind (2 charges), or wind wall (1 charge).\n\n***Ring of Earth Elemental command.*** You can expend 2 of the ring's charges to cast dominate monster on an earth elemental. In addition, you can move in difficult terrain that is composed of rubble, rocks, or dirt as if it were normal terrain. You can also speak and understand Terran.\n\nIf you help slay an earth elemental while attuned to the ring, you gain access to the following additional properties:\n\nYou have resistance to acid damage.\n\nYou can move through solid earth or rock as if those areas were difficult terrain. If you end your turn there, you are shunted out to the nearest unoccupied space you last occupied.\n\nYou can cast the following spells from the ring, expending the necessary number of charges: stone shape (2 charges), stoneskin (3 charges), or wall of stone (3 charges).\n\n***Ring of Fire Elemental command.*** You can expend 2 of the ring's charges to cast dominate monster on a fire elemental. In addition, you have resistance to fire damage. You can also speak and understand Ignan.\n\nIf you help slay a fire elemental while attuned to the ring, you gain access to the following additional properties:\n\nYou are immune to fire damage.\n\nYou can cast the following spells from the ring, expending the necessary number of charges: burning hands (1 charge), fireball (2 charges), and wall of fire (3 charges).\n\n***Ring of Water Elemental command.*** You can expend 2 of the ring's charges to cast dominate monster on a water elemental. In addition, you can stand on and walk across liquid surfaces as if they were solid ground. You can also speak and understand Aquan.\n\nIf you help slay a water elemental while attuned to the ring, you gain access to the following additional properties:\n\nYou can breathe underwater and have a swimming speed equal to your walking speed.\n\nYou can cast the following spells from the ring, expending the necessary number of charges: create or destroy water (1 charge), control water (3 charges), ice storm (2 charges), or wall of ice (3 charges).", null));
		yield return Item("ring-of-elemental-command-air", "ring-of-elemental-command", 1, MagicItemType.Ring, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(5, ItemRecharge.LongRest, "1d4+1"),
			("Anello del comando degli elementali dell'aria", "Anello, leggendario (richiede sintonia)",
			"", null),
			("Ring of Air Elemental Command", "Ring, legendary (requires attunement)",
			"", null));
		yield return Item("ring-of-elemental-command-earth", "ring-of-elemental-command", 2, MagicItemType.Ring, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(5, ItemRecharge.LongRest, "1d4+1"),
			("Anello del comando degli elementali della terra", "Anello, leggendario (richiede sintonia)",
			"", null),
			("Ring of Earth Elemental Command", "Ring, legendary (requires attunement)",
			"", null));
		yield return Item("ring-of-elemental-command-fire", "ring-of-elemental-command", 3, MagicItemType.Ring, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(5, ItemRecharge.LongRest, "1d4+1"),
			("Anello del comando degli elementali del fuoco", "Anello, leggendario (richiede sintonia)",
			"", null),
			("Ring of Fire Elemental Command", "Ring, legendary (requires attunement)",
			"", null));
		yield return Item("ring-of-elemental-command-water", "ring-of-elemental-command", 4, MagicItemType.Ring, ItemRarity.Legendary, true, ContentSource.Srd51,
			Charges(5, ItemRecharge.LongRest, "1d4+1"),
			("Anello del comando degli elementali dell'acqua", "Anello, leggendario (richiede sintonia)",
			"", null),
			("Ring of Water Elemental Command", "Ring, legendary (requires attunement)",
			"", null));
	}
}
